// Einmal die Adresse eurer Zeiterfassung eintragen, ohne abschließenden Schrägstrich.
const platformUrl = 'https://dienstplan.hemingway-hilden.de';
// Optional: bekannte Absenderadresse exakt eintragen. Leer = alle PDFs dieses dedizierten Postfachs.
const allowedSender = '';
// Vollständiger SFTP-Pfad. /share ist bei QNAP üblich; beim List-Test prüfen.
const qnapBasePath = '/share/Buchhaltung/Kassendoku';
return $input.all().map((item, i) => ({json: {...item.json, platform_url: platformUrl.replace(/\/$/, ''), allowed_sender: allowedSender.toLowerCase(), qnap_base_path: qnapBasePath}, binary: item.binary, pairedItem: {item: i}}));

const result = [];
for (const [i, item] of $input.all().entries()) {
  const from = item.json.from;
  const sender = (from?.value?.[0]?.address || (typeof from === 'string' ? (from.match(/<([^>]+)>/)?.[1] || from) : '')).trim().toLowerCase();
  if (item.json.allowed_sender && item.json.allowed_sender !== sender) continue;
  for (const file of Object.values(item.binary || {})) {
    if (file.mimeType !== 'application/pdf' && !/\.pdf$/i.test(file.fileName || '')) continue;
    result.push({json: {platform_url: item.json.platform_url, qnap_base_path: item.json.qnap_base_path, message_id: String(item.json.messageId || item.json.headers?.['message-id'] || item.json.uid || '').slice(0, 500)}, binary: {data: file}, pairedItem: {item: i}});
  }
}
return result;

// Bei nicht lesbaren/gescannten PDFs wird trotzdem das Original übertragen.
// Ohne auswertbaren Text bleibt die Tageszuordnung in der Plattform offen.
const original = $('PDF-Anhaenge').item;
return {json: {platform_url: original.json.platform_url, qnap_base_path: original.json.qnap_base_path, message_id: original.json.message_id, extracted_text: typeof $json.text === 'string' ? $json.text.slice(0, 1000000) : ''}, binary: original.binary};

// Das Geschäftstagsdatum kommt aus der bestätigten Plattform-Antwort, nicht aus der Mailzeit.
const original = $('Original und Metadaten').item;
const id = String($json.id ?? '');
if (!/^[1-9]\d*$/.test(id)) throw new Error('Die Plattform hat keine gültige Bericht-ID bestätigt.');
if (!original.binary?.data) throw new Error('Original-PDF im Binärfeld data fehlt.');
const base = String(original.json.qnap_base_path || '').replace(/\/+$/, '');
if (!base.startsWith('/') || base.split('/').includes('..') || base.includes('\\')) {
  throw new Error('Bitte einen vollständigen QNAP-SFTP-Basispfad ohne .. konfigurieren.');
}
const date = $json.business_date;
let folder = 'Unzugeordnet';
let datePart = 'unzugeordnet';
if (date != null && date !== '') {
  if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error('Ungültiger Geschäftstag in der Plattform-Antwort.');
  const parsed = new Date(date + 'T12:00:00Z');
  if (!Number.isFinite(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== date) throw new Error('Ungültiges Kalenderdatum.');
  folder = date.slice(0, 4) + '/' + date.slice(5, 7);
  datePart = date;
}
const filename = $json.archive_filename;
if (typeof filename !== 'string' || !/^Z-Bericht_(?:\d{4}-\d{2}-\d{2}|unzugeordnet)_(?:Z-\d{1,20}(?:_Beleg-[a-f0-9]{12})?|Beleg-[a-f0-9]{12})\.pdf$/.test(filename)) {
  throw new Error('Gültiger Archivdateiname mit Z-Berichtsnummer fehlt. Bitte Plattform aktualisieren.');
}
return {json: {...$json, qnap_path: `${base}/${folder}/${filename}`}, binary: original.binary};
